DROP TABLE IF EXISTS `edge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `edge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `dh1` int(11) NOT NULL,
  `kod` varchar(4) NOT NULL,
  `dh2` int(11) NOT NULL,
  `universum_id` int(11) NOT NULL DEFAULT '1',
  `strength` tinyint(3) unsigned DEFAULT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'candidate',
  `source` varchar(32) DEFAULT NULL,
  `rationale` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_edge` (`dh1`,`dh2`,`kod`,`universum_id`),
  KEY `dh1` (`dh1`),
  KEY `dh2` (`dh2`),
  KEY `kod` (`kod`)
) ENGINE=InnoDB AUTO_INCREMENT=1893 DEFAULT CHARSET=utf8;
