/*!40000 ALTER TABLE `relevant` DISABLE KEYS */;
INSERT INTO `relevant` VALUES ('0','no data','Служебный код: связь не установлена или не проверялась.','Любая непроверенная пара.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('1','incomparable','У понятий нет общего рода и основания для сравнения объёмов.','стол — честность.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('10','full inclusion (subordination) [deprecated]','УСТАРЕВШИЙ: слито с кодом 14. Включение объёма понятия в онтологии всегда является родовидовым отношением.','Использовать kod 14.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('11','universe (discourse context)','Базовый контекст, в рамках которого сравниваются объёмы понятий и истинны связи: бытовой, научный, или конкретная область (биология, медицина). Одна и та же пара понятий может иметь разные связи в разных универсумах. Исчерпывающие отношения (64) определены только внутри заданного универсума.','в бытовом универсуме: томат — овощ; в универсуме биологии: томат — фрукт (ягода).',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('12','domain-related','Принадлежность понятия к научной или иной области знаний (домену).','спина — анатомия; интеграл — математика.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('13','family (genus-to-genus) [deprecated]','УСТАРЕВШИЙ: слито с кодом 14. Родовое отношение едино на всех уровнях таксономии.','Использовать kod 14.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('14','genus (is-a)','Вид включён в род: dh1 — вид (или единичное понятие), dh2 — род. Наследование признаков сверху вниз, транзитивно. Пары только внутри одного корня.','стол — мебель; Лондон — столица (единичное понятие как вид).',NULL,NULL,NULL,NULL,NULL,0,1,NULL),('15','essential attribute','Признак, без которого предмет не относится к данному виду; входит в определение понятия. dh2 — признак (корень \'свойство\'), dh1 — предмет.','разумность — человек; наличие страниц — книга.',17,NULL,18,NULL,NULL,0,0,NULL),('20','non-essential attribute','Признак или компонент с неустановленной степенью (заголовок серии 21-27). Между предметом и свойством — атрибуция; между двумя предметами — компонентность (меронимия).','Промежуточный код, пока степень не вычислена.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('21','inherent attribute (inseparable part/phase)','Встречается всегда или почти всегда (степень >= 90%), но не входит в определение вида. Для пары предмет-предмет: неотделимая деталь.','двигатель — автомобиль; цвет глаз — человек.',17,19,18,17,19,0,0,NULL),('23','frequent attribute','Встречается обычно (степень 50-90%). Для пары предмет-предмет: типичный компонент.','колёса — автомобиль (бывают гусеничные).',17,19,18,17,19,0,0,NULL),('25','occasional attribute','Встречается иногда (степень 10-50%).','борода — мужчина; балкон — квартира.',17,19,18,17,19,0,0,NULL),('27','rare attribute','Встречается редко (степень < 10%). Для пары предмет-предмет: опциональная деталь.','спойлер — автомобиль; веснушки — человек.',17,19,18,17,19,0,0,NULL),('30','coextensive (equal scope)','Объёмы совпадают полностью, содержания различны. Каждый элемент одного есть элемент другого.','утренняя звезда — вечерняя звезда (Венера).',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('40','overlapping','Объёмы частично совпадают, степень не установлена (заголовок серии 41-48).','студент — спортсмен.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('41','full overlap with possible exception [deprecated]','УСТАРЕВШИЙ: граница с кодами 30 и 43 не определена. Использовать 30 (полное совпадение) или 43 (сильное пересечение).','Использовать kod 30 или 43.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('43','strong overlap','Совместная часть покрывает более половины объёма меньшего понятия (степень 50-90%).','собака — домашнее животное (как пересечение владения).',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('45','roughly equal overlap','Совместная часть составляет около половины объёма каждого понятия (степень 40-60% в обе стороны).','учёный — преподаватель.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('47','slight overlap','Совместная часть мала (степень < 10%).','певец — шахтёр.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('48','possible overlap','Модальный код: пересечение не зафиксировано статистически, но логически не запрещено.','певец — шахтёр (до проверки данных).',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('49','complementary [deprecated]','УСТАРЕВШИЙ: слито с кодом 62. Системные пары (ключ — замок) взаимно предполагают друг друга.','Использовать kod 62.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('60','incompatible','Объёмы не пересекаются, степень/тип не установлены (заголовок серии 61-64).','Промежуточный код.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('61','coordinate (co-hyponyms)','Виды одного рода, объёмы не пересекаются; не являются ни контрарными, ни контрадикторными.','тополь — берёза (виды деревьев).',NULL,NULL,NULL,NULL,NULL,1,0,'61'),('62','mutually implying (converses)','Взаимная импликация существования; включает конверсивные (обратные) роли одного отношения и системные пары.','муж — жена; купить — продать; северный полюс — южный полюс.',NULL,NULL,NULL,NULL,NULL,1,0,'62'),('63','contrary (opposite)','Крайние виды одного рода, между ними есть середина; не могут быть истинны одновременно, но могут быть оба ложны.','белый — чёрный; храбрость — трусость.',NULL,NULL,NULL,NULL,NULL,1,0,'63'),('64','contradictory','Исчерпывающая дихотомия A / не-A: не могут быть одновременно ни истинны, ни ложны.','живой — мёртвый; чётный — нечётный.',NULL,NULL,NULL,NULL,NULL,1,0,'64'),('70','causal (produces)','dh1 — причина, dh2 — следствие. Связь между корнями \'действие\'/\'предмет\'. Транзитивно по цепочкам причин.','огонь — дым; вирус — болезнь.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('71','hindrance (prevents)','dh1 препятствует или устраняет dh2 (отрицательная каузальность).','прививка — болезнь; тормоз — движение.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('72','temporal precedence','dh1 типично предшествует dh2 в одном процессе. Направленное, нетранзитивно в обратную сторону.','посев — уборка; гроза — ливень.',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('73','simultaneity','dh1 и dh2 типично происходят одновременно как стороны одного события. Симметрично.','гром — молния.',NULL,NULL,NULL,NULL,NULL,1,0,'73'),('74','dependence','dh1 функционально зависит от dh2: не существует или не работает без него. Направленное.','application software — operating system',NULL,NULL,NULL,NULL,NULL,0,0,NULL),('80','function (purpose)','dh1 (предмет) служит для dh2 (действие). Связь корней \'предмет\' -> \'действие\'.','нож — резать; мост — соединять.',17,NULL,19,NULL,NULL,0,0,NULL),('81','material','dh1 (предмет) изготовлен из dh2 (вещество). Связь \'предмет\' -> \'вещество\'.','стол — дерево; монета — металл.',17,NULL,21,NULL,NULL,0,0,NULL),('82','agent','dh1 (предмет) способен производить dh2 (действие). Связь \'предмет\' -> \'действие\'.','птица — летать; человек — мыслить.',17,NULL,19,NULL,NULL,0,0,NULL),('83','patient (object of action)','dh1 (действие) типично направлено на dh2 (предмет). Связь \'действие\' -> \'предмет\'.','читать — книга; строить — сооружение.',19,NULL,17,18,NULL,0,0,NULL);
